function HasPolynomialSolutionLinear(q):
    dq <- degree(q)
    if dq >= 1:
        # deg(q*p) = dq + n >= n+1 > n-2 >= deg(p'')
        return FALSE            # no nonzero polynomial solution
    else:
        return TRUE             # deg q <= 0: not forbidden by degree counting

function RiccatiHasPolynomialSolution():
    # u' + u^2 = x
    # deg u = 0  -> LHS degree <= 0 != 1
    # deg u >= 1 -> deg(u^2) = 2 deg u >= 2 != 1
    return FALSE

function AiryPolynomialCertificate(q = x):
    dq <- degree(q)
    if dq >= 1:
        return "deg(q*p) >= n+1 > n-2 >= deg(p''): no nonzero solution"
    else:
        return "deg q <= 0: degree counting does not forbid solutions"
